SELECT ("yk"."budget" / NULLIF("om"."budget", 0))::numeric AS "times_more"
FROM (SELECT "budget" FROM "advertisements" WHERE "meeting_name" = 'Yearly Kickoff') AS "yk",
     (SELECT "budget" FROM "advertisements" WHERE "meeting_name" = 'October Meeting') AS "om";

SELECT SUM("spend") AS "total_expense"
FROM "ad_campaign_pacing"
WHERE "spend_date" = DATE '2019-08-20';
